      "claim": "Vorinostat, a small polar amide-containing drug, has approximately 43% absolute oral bioavailability in fasting humans, supporting that the query's amide/heteroaromatic profile can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ondansetron, a small heteroaromatic drug, has 50–65% absolute oral bioavailability in fasted volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "PEMA, a small neutral amide, is 91 ± 4.4% orally bioavailable in normal volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Seliciclib, an aromatic heterocyclic drug, shows good oral bioavailability in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small nitroimidazole amide; the closest high-transfer analogue misonidazole (89–100% F in humans) and multiple other small-molecule drugs with high oral bioavailability support F≥20%. The only low-F record (brexanolone) has zero transferability and a steroidal scaffold, so it is not informative. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the exact query molecule.",
    "No data on metabolic stability or transporter efflux for the query's amide linkage.",
    "Misonidazole is the closest analogue but lacks the benzylamide substituent; extrapolation assumes similar absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

